331:             }
332:             if (log.IsTraceEnabled)
333:             {
334:                 log.Trace(msg);
335:             }
336: 
337:             // Any DNS-SD answers?
338: 
339:             var sd = msg.Answers
340:                 .OfType<PTRRecord>()
341:                 .Where(ptr => ptr.Name.IsSubdomainOf(LocalDomain));
342:             foreach (var ptr in sd)
343:             {
344:                 if (ptr.Name == ServiceName)
345:                 {
346:                     ServiceDiscovered?.Invoke(this, ptr.DomainName);
347:                 }
348:                 else if (ptr.TTL == TimeSpan.Zero)
349:                 {
350:                     var args = new ServiceInstanceShutdownEventArgs
351:                     {
352:                         ServiceInstanceName = ptr.DomainName,
353:                         Message = msg
354:                     };
355:                     ServiceInstanceShutdown?.Invoke(this, args);
356:                 }
357:                 else
358:                 {
359:                     var args = new ServiceInstanceDiscoveryEventArgs
360:                     {
361:                         ServiceInstanceName = ptr.DomainName,
