369:         void OnQuery(object sender, MessageEventArgs e)
370:         {
371:             var request = e.Message;
372: 
373:             if (log.IsDebugEnabled)
374:             {
375:                 log.Debug($"Query from {e.RemoteEndPoint}");
376:             }
377:             if (log.IsTraceEnabled)
378:             {
379:                 log.Trace(request);
380:             }
381: 
382:             // Determine if this query is requesting a unicast response
383:             // and normalise the Class.
384:             var QU = false; // unicast query response?
385:             foreach (var r in request.Questions)
386:             {
387:                 if (((ushort)r.Class & 0x8000) != 0)
388:                 {
389:                     QU = true;
390:                     r.Class = (DnsClass)((ushort)r.Class & 0x7fff);
391:                 }
392:             }
393: 
394:             var response = NameServer.ResolveAsync(request).Result;
395: 
396:             if (response.Status != MessageStatus.NoError)
397:             {
398:                 return;
399:             }
400: 
401:             // Many bonjour browsers don't like DNS-SD response
402:             // with additional records.
403:             if (response.Answers.Any(a => a.Name == ServiceName))
404:             {
405:                 response.AdditionalRecords.Clear();
406:             }
407: 
408:             if (AnswersContainsAdditionalRecords)
409:             {
410:                 response.Answers.AddRange(response.AdditionalRecords);
411:                 response.AdditionalRecords.Clear();
412:             }
413: 
414:             if (!response.Answers.Any(a => a.Name == ServiceName))
415:             {
416:                 ;
417:             }
418: 
419:             if (QU)
420:             {
421:                 // TODO: Send a Unicast response if required.
422:                 Mdns.SendAnswer(response, e);
423:             }
424:             else
425:             {
426:                 Mdns.SendAnswer(response, e);
427:             }
428: 
429:             if (log.IsDebugEnabled)
430:             {
431:                 log.Debug($"Sending answer");
432:             }
433:             if (log.IsTraceEnabled)
434:             {
435:                 log.Trace(response);
436:             }
